function topoSort(nodes, edges) {
  // Build adjacency list and in‑degree count.
  const adj = {};
  const indeg = {};
  for (const n of nodes) {
    adj[n] = [];
    indeg[n] = 0;
  }

  for (const [from, to] of edges) {
    // Self‑loop is a cycle.
    if (from === to) return null;

    // Guard against duplicate edges – only count once.
    if (!adj[from].includes(to)) {
      adj[from].push(to);
      indeg[to]++;
    }
  }

  // Initialise the set of nodes with no incoming edges.
  // We use a sorted array so that we can always pick the
  // lexicographically smallest ready node in O(log n).
  const ready = nodes.filter(n => indeg[n] === 0).sort();

  const result = [];

  while (ready.length > 0) {
    // Pick the smallest lexicographic node.
    const node = ready.shift(); // removes the first (smallest) element
    result.push(node);

    // Decrease in‑degree of neighbours.
    for (const neighbour of adj[node]) {
      indeg[neighbour]--;
      if (indeg[neighbour] === 0) {
        // Insert neighbour into ready keeping it sorted.
        // Because the array is small (at most `nodes.length`), a simple
        // binary‑search insert is fine, but a linear insert is also acceptable.
        let lo = 0, hi = ready.length;
        while (lo < hi) {
          const mid = (lo + hi) >> 1;
          if (ready[mid] < neighbour) lo = mid + 1;
          else hi = mid;
        }
        ready.splice(lo, 0, neighbour);
      }
    }
  }

  // If we didn't process every node, a cycle exists.
  if (result.length !== nodes.length) return null;

  return result;
}
